def transform(grid):
    # Replace the right-hand half of a partial marker row, keyed by the full marker row.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    full_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    # Infer foreground as the color of any non-background horizontal run, while
    # the full-width run serves as the key for recoloring the missing part.
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    bg = max(counts, key=counts.get)
    marker = next((c for c,n in counts.items() if c != bg), None)
    if marker is None:
        return out
    for r,row in enumerate(grid):
        if marker not in row:
            continue
        indices = [c for c,v in enumerate(row) if v == marker]
        if len(indices) == w:
            continue
        # recolor background immediately following the marker run
        end = max(indices) + 1
        for c in range(end, w):
            if row[c] == bg:
                out[r][c] = 1
    return out
